/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.LinkedHashMap;
import java.util.Map;

import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;

/**
 * Channel {@code webhook}: POST of a JSON to the target of the rule, with a {@code text} field that
 * Slack and Teams incoming webhooks show as is. A short timeout and three attempts; if all fail,
 * the alert keeps its notice pending and the minute scheduler retries it.
 */
@ApplicationScoped
public class WebhookAlertChannel implements AlertChannel {

  private static final int ATTEMPTS = 3;

  private final ObjectMapper mapper = new ObjectMapper();
  private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5))
      .followRedirects(HttpClient.Redirect.NEVER).build();

  @Override
  public boolean accepts(final String channel) {
    return "webhook".equals(channel);
  }

  @Override
  public void deliver(final AlertNotification notification) {
    String url = null == notification.targets() ? "" : notification.targets().trim();
    if (!url.startsWith("https://") && !url.startsWith("http://")) {
      throw new IllegalArgumentException(
          "The webhook of the rule " + notification.ruleName() + " is not an http(s) URL");
    }
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("text", (notification.firing() ? "🔴 " : "✅ ") + notification.ruleName() + ": "
        + notification.summary() + (null == notification.link() ? "" : " " + notification.link()));
    body.put("status", notification.status());
    body.put("rule", notification.ruleName());
    body.put("trigger", notification.trigger());
    body.put("summary", notification.summary());
    body.put("link", notification.link());
    body.put("details", notification.details());
    RuntimeException last = null;
    for (int attempt = 1; attempt <= ATTEMPTS; attempt++) {
      try {
        HttpRequest request = HttpRequest.newBuilder(URI.create(url))
            .timeout(Duration.ofSeconds(10)).header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body))).build();
        HttpResponse<Void> response = http.send(request, HttpResponse.BodyHandlers.discarding());
        if (response.statusCode() / 100 == 2) {
          return;
        }
        last = new IllegalStateException("Webhook answered " + response.statusCode());
      } catch (IOException ex) {
        last = new IllegalStateException("Webhook failed: " + ex.getMessage(), ex);
      } catch (InterruptedException ex) {
        Thread.currentThread().interrupt();
        throw new IllegalStateException("Interrupted", ex);
      }
    }
    throw last;
  }
}
